for n, s in SPECS do
	local ok, res = pcall(function() return IS:LoadAsset(s.id) end)
	if not ok then table.insert(log, s.name .. " LOAD FAIL " .. tostring(res)) continue end
	local m = Instance.new("Model")
	m.Name = s.name
	local meshes = {}
	for _, d in res:GetDescendants() do
		if d:IsA("MeshPart") then table.insert(meshes, d) end
	end
	-- порядок деталей = порядок материалов в GLB; сверяем ещё и по размеру
	local used = {}
	local bad = 0
	local root = res:FindFirstChildWhichIsA("Model")
	local pv = root and root:GetPivot() or CFrame.new()
	for _, mp in meshes do
		local best, bd = nil, math.huge
		for j, c in s.cols do
			if not used[j] then
				local sz = mp.Size
				local dd = math.abs(sz.X - c[5]) + math.abs(sz.Y - c[6]) + math.abs(sz.Z - c[7])
				if dd < bd then best, bd = j, dd end
			end
		end
		if best then
			used[best] = true
			if bd > 0.05 then bad += 1 end
			local c = s.cols[best]
			mp.Color = Color3.fromRGB(c[1], c[2], c[3])
			mp.Material = if c[4] then Enum.Material.Neon else Enum.Material.SmoothPlastic
			mp.CastShadow = not c[4]
		end
		mp.Anchored = true
		mp.CanCollide = false
		mp.CanQuery = false
		mp.CanTouch = false
		mp.Massless = true
		mp:SetAttribute("OrigColor", mp.Color)
		mp:SetAttribute("OrigMaterial", mp.Material.Name)
		-- координаты GLB: импорт развернул модель на 180 градусов вокруг Y
		local rel = pv:ToObjectSpace(mp.CFrame)
		mp.CFrame = CFrame.Angles(0, math.pi, 0) * rel
		mp.Parent = m
	end
	m.WorldPivot = CFrame.new()
	if s.px then
		m:SetAttribute("PairX", s.px)
		m:SetAttribute("PairY", s.py)
	end
	local _, sz = m:GetBoundingBox()
	table.insert(log, string.format("%s parts=%d/%d badsize=%d size=%.2f,%.2f,%.2f", s.name, #meshes, #s.cols, bad, sz.X, sz.Y, sz.Z))
	m.Parent = lib
	res:Destroy()
	if n % 5 == 0 then task.wait() end
end
lib.Parent = RS
return table.concat(log, "\n")